class Solution {
public:
    int distinctPoints(string s, int k) {
        int n = (int)s.size();
        vector<long long> prefX(n + 1, 0), prefY(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            long long dx = 0, dy = 0;
            switch (s[i]) {
                case 'U': dy = 1; break;
                case 'D': dy = -1; break;
                case 'L': dx = -1; break;
                case 'R': dx = 1; break;
            }
            prefX[i + 1] = prefX[i] + dx;
            prefY[i + 1] = prefY[i] + dy;
        }
        long long totalX = prefX[n];
        long long totalY = prefY[n];

        struct PairHash {
            size_t operator()(const pair<long long,long long>&p) const noexcept {
                return (static_cast<size_t>(p.first) << 32) ^ static_cast<size_t>(p.second);
            }
        };
        unordered_set<pair<long long,long long>, PairHash> seen;
        seen.reserve(n);

        for (int i = 0; i + k <= n; ++i) {
            long long subX = prefX[i + k] - prefX[i];
            long long subY = prefY[i + k] - prefY[i];
            long long fx = totalX - subX;
            long long fy = totalY - subY;
            seen.emplace(fx, fy);
        }
        return (int)seen.size();
    }
};
